package com.hbm.client.entity.maskman;
import com.hbm.entity.mob.maskman.MaskMan;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.resources.ResourceLocation;
public final class MaskManRenderer extends MobRenderer<MaskMan,MaskManModel>{public MaskManRenderer(EntityRendererProvider.Context context){super(context,new MaskManModel(),1);shadowStrength=0;}@Override public ResourceLocation getTextureLocation(MaskMan entity){return ResourceLocation.parse("hbm:textures/entity/maskman.png");}@Override public void render(MaskMan entity,float yaw,float partial,PoseStack poses,MultiBufferSource buffers,int light){model.buffers=buffers;try{super.render(entity,yaw,partial,poses,buffers,light);}finally{model.buffers=null;}}}
